sys_script_client.script:
function onLoad() {

    // Check if the current form is in a Workspace
    g_form.setDisplay('participant_id', true);
    g_form.setDisplay('state', true);
    var participantIDCheck = g_form.getValue('participant_id');
    if (((participantIDCheck == "")) || ((g_form.getValue('assigned_to') != g_user.userID) && (!g_form.isNewRecord()))) {
        g_form.disableAttachments();
    } else {
        g_form.clearMessages();
        g_form.enableAttachments();
    }
    g_form.setDisplay('participant_id', false);
}
